import {projectMiniature} from './miniature-raster.js?v=architecture-collection-44';
// Cosmetic match activity uses the same paused scenery clock as fountains and vehicles.
export function stadiumMatchState(renderer,root){const c=renderer.getCity(),size=root.stadiumSize??4;let access=false,active=root.type==='stadium'&&renderer.layer==='city'&&c.finance.roadCondition>20;for(let y=root.y;y<root.y+size;y++)for(let x=root.x;x<root.x+size;x++){const t=c.tiles[y*c.size+x];if(!t||t.root!==root.root||!t.powered||t.fire||t.rubble||t.radiation)active=false;access ||= !!t?.roadIds?.length;}return{active:active&&access,time:renderer.preferences?.sceneryAnimations===false||renderer.reducedMotion.matches?0:renderer.vehicleTime};}
export function stadiumActors(time=0,active=true){if(!active)return[];const phase=time*.65,actors=[];for(let team=0;team<2;team++)for(let i=0;i<6;i++){const side=team?1:-1;actors.push({point:[(i%3-1)*.13+Math.sin(phase+i+team)*.025,side*(.09+Math.floor(i/3)*.12)+Math.cos(phase+i*2)*.025,.10],color:team?'#ebc67a':'#78b7d0',ball:false});}actors.push({point:[Math.sin(phase)*.16,Math.cos(phase)*.20,.08],color:'#f8f3d9',ball:true});return actors;}
export function stadiumMatchPixels(time,rotation,depth,active=true){const pixels=[];for(const actor of stadiumActors(time,active)){const [x,y,z]=actor.point,[px,py]=projectMiniature(actor.point,rotation),[rx,ry]=rotation===0?[x,y]:rotation===1?[-y,x]:rotation===2?[-x,-y]:[y,-x],distance=rx+ry+z;for(let dy=actor.ball?-1:-4;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=Math.round(px)+dx,yy=Math.round(py)+dy,index=yy*512+xx;if(xx<0||xx>=512||yy<0||yy>=512||distance<depth[index]-1e-7)continue;pixels.push({x:xx,y:yy,color:!actor.ball&&dy===-4?'#dcc5a1':actor.color});}}return pixels;}
